import{d as g,C as r,o as h,c as d,j as i,a,E as e,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const x=JSON.parse('{"title":"中庸·第22章","description":"《中庸》第 22 章——唯天下至诚，为能尽其性：尽己之性、尽人之性、尽物之性，赞天地之化育，与天地参。","frontmatter":{"title":"中庸·第22章","description":"《中庸》第 22 章——唯天下至诚，为能尽其性：尽己之性、尽人之性、尽物之性，赞天地之化育，与天地参。","category":"guide","aliases":["第22章","中庸第22章","尽其性"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-22.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-22.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/zhongyong/chapter-22.md"},b=g({...m,setup(p){const o=[{id:"jinxing",label:"唯天下至诚 · 为能尽其性",showLabel:!0,sentences:[["唯天下",{text:"至诚",glossary:"zhicheng"},"，为能",{text:"尽其性",glossary:"jinqixing"},"；"]],note:"「唯天下至诚，为能尽其性」——只有天下至诚的人，才能充分发挥自己本有的本性。此章即由「尽己之性」层层推展出去。"},{id:"tuikai",label:"尽人之性 · 尽物之性 · 赞天地化育 · 与天地参",showLabel:!0,sentences:[["能尽其性，则能尽人之性；能尽人之性，则能尽物之性；能尽物之性，则可以",{text:"赞",glossary:"zan"},"天地之",{text:"化育",glossary:"huayu"},"；可以赞天地之化育，则可以",{text:"与天地参",glossary:"yutiandican"},"矣。"]],note:"由己而人而物：「能尽其性，则能尽人之性；能尽人之性，则能尽物之性」；再进一步，「可以赞天地之化育」（赞＝助成），「则可以与天地参矣」——与天地并立而为三。此章极言至诚之功效。"}],s=[{id:"zhicheng",term:"至诚",pinyin:"zhì chéng",meaning:"朱注：「天下至诚，谓圣人之德之实，天下莫能加也。」"},{id:"jinqixing",term:"尽其性",pinyin:"jìn qí xìng",meaning:"充分实现自己的本性。朱注：「尽其性者德无不实，故无人欲之私，而天命之在我者，察之由之，巨细精粗，无毫发之不尽也。」"},{id:"zan",term:"赞",pinyin:"zàn",meaning:"助。赞天地之化育，即赞助天地的化育。"},{id:"huayu",term:"化育",pinyin:"huà yù",meaning:"天地的化生养育。"},{id:"yutiandican",term:"与天地参",pinyin:"yǔ tiān dì sān",meaning:"参：读 sān。与天地并立为三。朱注：「谓与天地并立为三也。」"}];return(c,n)=>{const l=r("DaoTextReading"),t=r("DaoKeywordCards");return h(),d("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第22章",tabindex:"-1"},[a("中庸·第22章 "),i("a",{class:"header-anchor",href:"#中庸·第22章","aria-label":'Permalink to "中庸·第22章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[a("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,[a("第二十二章讲「至诚」的力量：由"),i("strong",null,"尽己之性"),a("开始，层层推开——尽人之性、尽物之性、赞天地之化育，最后「与天地参」。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),e(l,{colophon:"至诚尽性 · 赞化育 · 与天地参",tone:"ink",sections:o,glossary:s,"default-mode":"slips","aria-label":"中庸·第22章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[a("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),e(t,{items:[{term:"至诚",pinyin:["zhì","chéng"],meaning:"朱注：「天下至诚，谓圣人之德之实，天下莫能加也。」"},{term:"尽其性",pinyin:["jìn","qí","xìng"],meaning:"充分实现自己的本性。朱注：「德无不实，故无人欲之私。」"},{term:"赞",pinyin:["zàn"],meaning:"助。赞天地之化育，即赞助天地的化生养育。"},{term:"与天地参",pinyin:["yǔ","tiān","dì","sān"],meaning:"参读 sān：与天地并立为三。人在天地之间，不是旁观者。"}]}),e(t,{items:[{term:"人物之性",pinyin:["rén","wù","zhī","xìng"],meaning:"人与物的性。"},{term:"亦我之性",pinyin:["yì","wǒ","zhī","xìng"],meaning:"也就是我的性。朱注：「但以所赋形气不同而有异耳。」这一句是「推及人、物」的根据。"}]}),n[4]||(n[4]=u('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>唯天下至诚 · 为能尽其性</strong>：只有天下至诚的人，才能充分实现自己的本性。</p><p><strong>尽人之性 · 与天地参</strong>：能尽自己的性，就能尽他人的性；能尽他人的性，就能尽万物的性；能尽万物的性，就可以赞助天地的化育；能赞助天地的化育，就可以与天地并立为三了。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第二十二章只有一句，却把「至诚」的力量推到了极处：</p><p><strong>尽己之性 → 尽人之性 → 尽物之性 → 赞天地之化育 → 与天地参。</strong></p><p>一环扣一环，起点是「<strong>尽己之性</strong>」，终点是「与天地并立为三」。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它把「修身」推到了宇宙尺度</strong>：第 20 章讲为政在人、修身以道；本章进一步说，把「己之性」尽到了极处，这力量会依次通到人、物、天地。<strong>《大学》的八条目是「从外到内」，这里是「从内到外」。</strong></li><li><strong>朱注给了关键的一句</strong>：「人物之性，亦我之性，但以所赋形气不同而有异耳」——人、物的性与我的性<strong>本是同一个</strong>，所以「尽己之性」才可能推及人、物。这不是推己及人的类比，而是同源。</li><li><strong>「尽其性」的条件是无私</strong>：朱注说「德无不实，故<strong>无人欲之私</strong>」。又是这个字——从第 9 章「中庸不可能」、第 10 章「自胜其人欲之私」到这里，全篇的难处始终一致。</li><li><strong>「与天地参」是全篇人的位置的顶点</strong>：人不是天地间的一件物，而是能与天地并立为三的那一极。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>次序不能倒</strong>：想帮人、想成事，起点是「尽己之性」——先把自己做成那个样子。</li><li><strong>对「人物之性亦我之性」的体会</strong>：理解别人，前提是理解自己；自己能尽，才谈得上让人也能尽。</li><li><strong>「参」的姿态</strong>：做事不是在天地的安排里被动等，而是参与进去。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>只有天下至诚的人，才能把自己那份本性<strong>充分实现出来</strong>。</p><p>而这事一旦开始，就层层推下去：能尽自己的性，就能尽他人的性；能尽他人的性，就能尽万物的性；再往上，可以<strong>赞助天地的化育</strong>；再往上，能与天地<strong>并立为三</strong>。</p><p>这一章只有一句，却把人的位置抬高到了天地之间：<strong>你不是被安排的那一个，你是参与的那一个。</strong> 而起点很小——就是「把自己的性尽到」。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「尽己之性」——我的「性」是什么？我说得出来吗？</li><li>己 → 人 → 物 → 天地——这个次序，我是不是总想从中间开始？</li><li>「与天地参」——我把自己看作被安排的那一个，还是参与的那一个？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-21">中庸·第21章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-23">中庸·第23章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',23))])}}});export{x as __pageData,b as default};
